-- 산림재해 통합 플랫폼 초기 상태 전용 seed
-- 연속 위치·장비 상태·화선·RSSI 데이터는 테스트 서버가 생성한다.
-- 고정 UUID와 SIM-* 코드만 사용하며 재실행 시 이 seed 데이터만 교체한다.

BEGIN;
SET LOCAL statement_timeout = '30s';
SET LOCAL lock_timeout = '5s';
SET LOCAL TIME ZONE 'UTC';

DELETE FROM core.disaster_event
WHERE event_id IN (
  '10000000-0000-4000-8000-000000000001',
  '10000000-0000-4000-8000-000000000002'
);

DELETE FROM core.asset
WHERE asset_code LIKE 'SIM-%';

