COMMIT;

SELECT
  e.event_code,
  e.disaster_type,
  e.status,
  (SELECT count(*) FROM core.event_resource r WHERE r.event_id = e.event_id) AS initial_resources,
  (SELECT count(*) FROM core.personnel_position p WHERE p.event_id = e.event_id) AS initial_personnel_positions,
  (SELECT count(*) FROM core.asset_status s WHERE s.event_id = e.event_id) AS initial_asset_statuses
FROM core.disaster_event e
WHERE e.event_id IN (
  '10000000-0000-4000-8000-000000000001',
  '10000000-0000-4000-8000-000000000002'
)
ORDER BY e.event_code;
